types.MethbokeAddon.WeakFouriermanB.LocalSobol:
@MethbokeAddon.WeakFouriermanB.LocalSobolevFlow.initial_eq : ∀ {ν T : ℝ}
  (L : MethbokeAddon.WeakFouriermanB.LocalSobolevFlow ν T),
  LE.le.{0} 0 T →
    ∀ (a : SingularClosure.Field),
      SingularClosure.SmoothSigmaZero a →
        Eq.{1} (↑(L.state 0 0)) (SingularClosure.datumFourierCoeff a) → Eq.{1} (L.velocity 0) a

@MethbokeAddon.WeakFouriermanB.LocalSobolevFlow.physical_equation : ∀ {ν T : ℝ}
  (L : MethbokeAddon.WeakFouriermanB.LocalSobolevFlow ν T) (t : ℝ),
  Membership.mem.{0, 0} (Set.Ico.{0} 0 T) t →
    ∀ (x : SingularClosure.Vec),
      Eq.{1}
        (HAdd.hAdd.{0, 0, 0}
          (HAdd.hAdd.{0, 0, 0} (SingularClosure.timeDerivative L.velocity t x)
            (SingularClosure.convection (L.velocity t) x))
          (SingularClosure.gradient (L.pressure t) x))
        (HSMul.hSMul.{0, 0, 0} ν (SingularClosure.laplacian (L.velocity t) x))

@MethbokeAddon.WeakFouriermanB.LocalSobolevFlow.pressure_spacetime_smooth : ∀ {ν T : ℝ}
  (L : MethbokeAddon.WeakFouriermanB.LocalSobolevFlow ν T),
  LT.lt.{0} 0 T →
    ContDiffOn.{0, 0, 0} ℝ ∞ (fun z => L.pressure z.1 z.2) (MethbokeAddon.WeakFouriermanB.initialFrontSpacetime T)

@MethbokeAddon.WeakFouriermanB.LocalSobolevFlow.rhs_coeff : ∀ {ν T : ℝ}
  (L : MethbokeAddon.WeakFouriermanB.LocalSobolevFlow ν T) (r : ℕ) (t : ℝ),
  Membership.mem.{0, 0} (Set.Icc.{0} 0 T) t →
    Eq.{1} (↑(SingularClosure.fourierSobolevRhs ν r (L.state (HAdd.hAdd.{0, 0, 0} r 2) t)))
      (SingularClosure.fullFourierRhs ν (L.state 0 t))

@MethbokeAddon.WeakFouriermanB.LocalSobolevFlow.state_all_mem : ∀ {ν T : ℝ}
  (L : MethbokeAddon.WeakFouriermanB.LocalSobolevFlow ν T) (t : ℝ),
  Membership.mem.{0, 0} (Set.Icc.{0} 0 T) t →
    ∀ (s : ℕ), Memℓp.{0, 0} (SingularClosure.sobolevWeightedCoeff s ↑(L.state 0 t)) 2

@MethbokeAddon.WeakFouriermanB.LocalSobolevFlow.time_smooth : ∀ {ν T : ℝ}
  (L : MethbokeAddon.WeakFouriermanB.LocalSobolevFlow ν T),
  LT.lt.{0} 0 T → ∀ (r : ℕ), ContDiffOn.{0, 0, 0} ℝ ∞ (L.state r) (Set.Icc.{0} 0 T)

@MethbokeAddon.WeakFouriermanB.LocalSobolevFlow.velocity_smoothSigmaZero : ∀ {ν T : ℝ}
  (L : MethbokeAddon.WeakFouriermanB.LocalSobolevFlow ν T) (t : ℝ),
  Membership.mem.{0, 0} (Set.Icc.{0} 0 T) t → SingularClosure.SmoothSigmaZero (L.velocity t)

@MethbokeAddon.WeakFouriermanB.LocalSobolevFlow.velocity_spacetime_smooth : ∀ {ν T : ℝ}
  (L : MethbokeAddon.WeakFouriermanB.LocalSobolevFlow ν T),
  LT.lt.{0} 0 T →
    ContDiffOn.{0, 0, 0} ℝ ∞ (fun z => L.velocity z.1 z.2) (MethbokeAddon.WeakFouriermanB.initialFrontSpacetime T)

@MethbokeAddon.WeakFouriermanB.LocalSobolevFlow.velocity_timeDerivative : ∀ {ν T : ℝ}
  (L : MethbokeAddon.WeakFouriermanB.LocalSobolevFlow ν T) (t : ℝ),
  Membership.mem.{0, 0} (Set.Ico.{0} 0 T) t →
